import {useMutation, type UseMutationResult} from '@github-ui/react-query'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'

type MemoryDisabledResponse = {
  memoryDisabled: boolean
  message?: string
}

export function useUpdateMemoryDisabledSetting(
  path: string,
): UseMutationResult<MemoryDisabledResponse, Error, boolean> {
  return useMutation({
    mutationFn: async (disabled: boolean) => {
      const response = await verifiedFetchJSON(path, {
        method: 'PUT',
        body: {
          memory_disabled: disabled,
        },
      })
      const data = (await response.json()) as unknown

      if (!response.ok) {
        const message =
          data && typeof data === 'object' && 'error' in data && typeof (data as {error?: string}).error === 'string'
            ? (data as {error: string}).error
            : data &&
                typeof data === 'object' &&
                'message' in data &&
                typeof (data as {message?: string}).message === 'string'
              ? (data as {message: string}).message
              : `Failed to update memory setting: ${response.status} ${response.statusText}`
        throw new Error(message)
      }

      if (!data || typeof data !== 'object' || !('memoryDisabled' in data)) {
        throw new Error('Invalid response when updating memory setting')
      }

      const value = data.memoryDisabled
      if (typeof value !== 'boolean') {
        throw new Error('Invalid response when updating memory setting')
      }

      return {memoryDisabled: value}
    },
  })
}
