import {ControlGroup} from '@github-ui/control-group'
import {Label} from '@primer/react'
import {InlineMessage} from '@primer/react/experimental'
import {useState} from 'react'
import {useUpdateMemoryDisabledSetting} from '../hooks/use-update-memory-disabled-setting'

type Props = {
  /** Path to the update_memory_disabled endpoint */
  endpoint: string
  /** Whether memory is currently disabled for this repository */
  initialDisabled: boolean
}

export function MemoryOptOutSettings({endpoint, initialDisabled}: Props) {
  const saveSetting = useUpdateMemoryDisabledSetting(endpoint)
  const [isSaving, setIsSaving] = useState<boolean>(false)
  const [isDisabled, setIsDisabled] = useState<boolean>(initialDisabled)
  const [errorMessage, setErrorMessage] = useState<string | null>(null)

  // The UI presents this as an "Allow memory" toggle while the API stores
  // the "disabled" value.
  const isAllowed = !isDisabled

  const handleToggle = async () => {
    setIsSaving(true)
    setErrorMessage(null)
    const nextDisabled = !isDisabled
    try {
      const result = await saveSetting.mutateAsync(nextDisabled)
      setIsDisabled(result.memoryDisabled)
    } catch (error) {
      setErrorMessage(error instanceof Error ? error.message : 'An error occurred saving memory settings.')
    } finally {
      setIsSaving(false)
    }
  }

  return (
    <ControlGroup.Item>
      <ControlGroup.Title id="copilot-memory-allow-label">
        <span className="d-inline-flex flex-items-center flex-wrap gap-2">
          <span>Allow Copilot to store and retrieve repository facts</span>
          <Label variant="success" aria-hidden="true">
            Preview
          </Label>
        </span>
      </ControlGroup.Title>
      <ControlGroup.Description id="copilot-memory-allow-description">
        When enabled, Copilot agents can store and retrieve repository facts. User preferences are not affected by this
        setting.
        {errorMessage && (
          <div role="status" aria-live="polite">
            <InlineMessage variant="critical" size="small" className="mt-1">
              {errorMessage}
            </InlineMessage>
          </div>
        )}
      </ControlGroup.Description>
      <ControlGroup.ToggleSwitch
        aria-labelledby="copilot-memory-allow-label"
        aria-describedby="copilot-memory-allow-description"
        checked={isAllowed}
        disabled={isSaving}
        onClick={e => {
          e.preventDefault()
          handleToggle()
        }}
      />
    </ControlGroup.Item>
  )
}
